const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const demoCourses=[
 {id:1,name:"Combined Mathematics",stream:"Physical Science",teacher:"Mr. Tharindu Jayasinghe",lessons:42,duration:"36 hours",desc:"Build strong foundations in pure and applied mathematics.",icon:"∑"},
 {id:2,name:"Biology",stream:"Biological Science",teacher:"Dr. Sachini Fernando",lessons:38,duration:"32 hours",desc:"Understand biological systems with clear visual explanations.",icon:"🧬"},
 {id:3,name:"Accounting",stream:"Commerce",teacher:"Mr. Dilan Peris",lessons:30,duration:"28 hours",desc:"Master accounting concepts and structured questions.",icon:"▤"},
 {id:4,name:"Information & Communication Technology",stream:"Technology",teacher:"Ms. Nadeesha Silva",lessons:35,duration:"30 hours",desc:"Learn ICT theory, practical concepts and exam techniques.",icon:"⌘"},
 {id:5,name:"Physics",stream:"Physical Science",teacher:"Mr. Tharindu Jayasinghe",lessons:40,duration:"34 hours",desc:"Explore mechanics, waves, electricity and modern physics.",icon:"⚛"},
 {id:6,name:"Economics",stream:"Commerce",teacher:"Ms. Amaya Perera",lessons:28,duration:"25 hours",desc:"Connect economic theory with real-world examples.",icon:"◉"}
];
const materials=[["Physics","2025 A/L Physics Past Paper","Past Paper","2025"],["Biology","Cell Biology Short Notes","Short Notes","2026"],["Combined Mathematics","Pure Maths Revision Paper","Revision Paper","2024"],["ICT","Database Systems MCQ Pack","MCQ","2025"],["Accounting","Financial Accounting Notes","PDF Notes","2026"],["Chemistry","Organic Chemistry Model Paper","Model Paper","2025"]];
function current(){return JSON.parse(localStorage.getItem("sl_current")||"null")}
function ensureUser(){if(!current()){location.href="login.html";return false}return true}
function initials(n){return (n||"SL").split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase()}
function nav(active,role="student"){const items=role==="admin"?[["Dashboard","admin.html","▦"],["Students","admin.html#students","♙"],["Teachers","admin.html#teachers","♧"],["Courses","courses.html","▤"],["Materials","materials.html","▧"],["Live Classes","live-classes.html","◷"],["Announcements","admin.html#announcements","◉"]]:role==="teacher"?[["Dashboard","teacher.html","▦"],["My Courses","courses.html","▤"],["Study Materials","materials.html","▧"],["Assignments","assignments.html","✎"],["Live Classes","live-classes.html","◷"]]:[["Dashboard","dashboard.html","▦"],["My Courses","courses.html","▤"],["Study Materials","materials.html","▧"],["Live Classes","live-classes.html","◷"],["Assignments","assignments.html","✎"],["Online Exams","quizzes.html","◎"],["My Profile","profile.html","♙"]];
return `<aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark">S</span> Smart<span>Learning</span></a><div class="side-label">Learning menu</div><nav class="side-nav">${items.map(([n,u,i])=>`<a class="${active===n?'active':''}" href="${u}"><span class="nav-emoji">${i}</span>${n}</a>`).join("")}</nav><div class="sidebar-bottom"><div class="side-label">Account</div><nav class="side-nav"><a href="profile.html"><span class="nav-emoji">⚙</span>Settings / Profile</a><button id="logoutBtn"><span class="nav-emoji">↪</span>Log out</button></nav></div></aside>`}
function shell(title,active,content,role="student"){const u=current();$("#app").innerHTML=`<div class="app-shell">${nav(active,role)}<main class="app-main"><header class="app-topbar"><h2>${title}</h2><div class="top-actions"><button class="icon-btn" id="darkToggle" title="Toggle dark mode">◐</button><button class="icon-btn" id="notifyBtn" title="Notifications">♧</button><div class="user-chip"><span class="user-avatar">${initials(u.name)}</span><span>${u.name}</span></div></div></header><section class="page-content">${content}</section></main></div><div class="modal-backdrop" id="modalBackdrop"><div class="modal" id="modalContent"></div></div>`;$("#logoutBtn")?.addEventListener("click",()=>{localStorage.removeItem("sl_current");location.href="index.html"});$("#darkToggle")?.addEventListener("click",()=>document.body.classList.toggle("dark"));$("#notifyBtn")?.addEventListener("click",()=>alert("You're all caught up!"));$$("[data-modal]").forEach(b=>b.addEventListener("click",()=>openModal(b.dataset.modal)))}
function openModal(type){const box=$("#modalBackdrop");let body=type==="edit"?`<h3>Edit profile</h3><label>Full name<input id="editName" value="${current().name}"></label><label>School<input id="editSchool" value="${current().school||''}"></label><label>District<input id="editDistrict" value="${current().district||''}"></label><div class="modal-actions"><button class="btn btn-light" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="saveProfile()">Save changes</button></div>`:`<h3>Action</h3><p>This demo action is ready for backend integration.</p><div class="modal-actions"><button class="btn btn-primary" onclick="closeModal()">Close</button></div>`;$("#modalContent").innerHTML=body;box.classList.add("open")}
function closeModal(){$("#modalBackdrop")?.classList.remove("open")}
function saveProfile(){let u=current();u.name=$("#editName").value;u.school=$("#editSchool").value;u.district=$("#editDistrict").value;localStorage.setItem("sl_current",JSON.stringify(u));closeModal();location.reload()}
function heading(title,sub,button=""){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function dashboard(){if(!ensureUser())return;let u=current();shell("Student dashboard","Dashboard",`${heading(`Good evening, ${u.name.split(" ")[0]} 👋`,"Here's your learning overview. Keep up the great work!")}<div class="grid-4"><div class="stat-card"><small>Enrolled courses</small><strong>04</strong><span>↑ 2 this term</span></div><div class="stat-card"><small>Lessons completed</small><strong>28</strong><span>↑ 6 this week</span></div><div class="stat-card"><small>Study hours</small><strong>36.5</strong><span>↑ 12% this month</span></div><div class="stat-card"><small>Average quiz score</small><strong>82%</strong><span>↑ 5% improvement</span></div></div><div class="content-grid"><div class="panel"><h3>My learning progress</h3><p class="panel-sub">Your course completion at a glance</p>${[["Combined Mathematics",72],["Physics",58],["ICT",86],["Chemistry",41]].map(([n,v])=>`<div class="progress-row"><b>${n}</b><span>${v}%</span></div><div class="progress-track"><span style="width:${v}%"></span></div>`).join("")}</div><div class="panel"><h3>Upcoming live classes</h3>${[["Physics: Electricity","Today · 7:00 PM"],["Combined Maths: Integration","Tomorrow · 4:30 PM"],["ICT: Database concepts","Friday · 6:00 PM"]].map(x=>`<div class="list-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span class="pill">Upcoming</span></div>`).join("")}<a class="action-link" href="live-classes.html">View schedule →</a></div></div><div class="content-grid"><div class="panel"><h3>Continue learning</h3>${demoCourses.slice(0,3).map(c=>`<div class="list-row"><div><strong>${c.name}</strong><small>${c.teacher} · ${c.lessons} lessons</small></div><a class="action-link" href="classroom.html">Continue →</a></div>`).join("")}</div><div class="panel"><h3>Latest announcements</h3><div class="list-row"><div><strong>2027 revision timetable published</strong><small>Today · Academic team</small></div><span class="pill orange-pill">New</span></div><div class="list-row"><div><strong>Mock examination registration</strong><small>Yesterday · Admin</small></div></div></div></div>`)}
function courses(){if(!ensureUser())return;const query=new URLSearchParams(location.search).get("stream")||"All streams";shell("Course catalogue","My Courses",`${heading("Explore A/L courses","Choose a subject and start learning.")}<div class="toolbar"><input id="courseSearch" placeholder="Search subjects or teachers…"><select id="streamFilter"><option>All streams</option>${["Physical Science","Biological Science","Commerce","Arts","Technology"].map(x=>`<option>${x}</option>`).join("")}</select></div><div class="course-grid" id="courseGrid"></div>`);$("#streamFilter").value=query;function render(){let q=$("#courseSearch").value.toLowerCase(),s=$("#streamFilter").value;$("#courseGrid").innerHTML=demoCourses.filter(c=>(s==="All streams"||c.stream===s)&&(`${c.name} ${c.teacher} ${c.stream}`.toLowerCase().includes(q))).map(c=>`<article class="course-card"><div class="course-cover">${c.icon}<span style="margin-left:auto;font-size:10px">${c.stream}</span></div><div class="course-info"><h3>${c.name}</h3><p>${c.desc}</p><div class="course-meta"><span>♙ ${c.teacher}</span><span>${c.lessons} lessons</span></div><button class="btn btn-primary" onclick="location.href='classroom.html'">Open course →</button></div></article>`).join("")||"<p>No courses match your search.</p>"}$("#courseSearch").addEventListener("input",render);$("#streamFilter").addEventListener("change",render);render()}
function materialPage(){if(!ensureUser())return;shell("Study materials","Study Materials",`${heading("Study resource library","Find notes, past papers and revision resources.")}<div class="toolbar"><input id="matSearch" placeholder="Search materials…"><select id="matSubject"><option>All subjects</option>${[...new Set(materials.map(m=>m[0]))].map(x=>`<option>${x}</option>`).join("")}</select><select id="matYear"><option>All years</option>${["2026","2025","2024"].map(x=>`<option>${x}</option>`).join("")}</select></div><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Subject</th><th>Type</th><th>Year</th><th>Action</th></tr></thead><tbody id="materialsBody"></tbody></table></div>`);function render(){let q=$("#matSearch").value.toLowerCase(),s=$("#matSubject").value,y=$("#matYear").value;$("#materialsBody").innerHTML=materials.filter(m=>(s==="All subjects"||m[0]===s)&&(y==="All years"||m[3]===y)&&m.join(" ").toLowerCase().includes(q)).map(m=>`<tr><td><b>${m[1]}</b></td><td>${m[0]}</td><td><span class="pill">${m[2]}</span></td><td>${m[3]}</td><td><button class="action-link" onclick="downloadDemo('${m[1]}')">Download ↓</button></td></tr>`).join("")}["matSearch","matSubject","matYear"].forEach(id=>$("#"+id).addEventListener("input",render));render()}
function downloadDemo(name){const blob=new Blob([`Smart Learning demo resource\\n\\n${name}\\n\\nThis is a sample downloadable resource placeholder. Connect your backend or replace this file with the real PDF.`],{type:"text/plain"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name.replaceAll(" ","-")+".txt";a.click();URL.revokeObjectURL(a.href)}
function classroom(){if(!ensureUser())return;let lessons=["Introduction and syllabus overview","Core concepts and definitions","Worked examples","Exam-style questions","Revision and recap"];let active=0;shell("Learning classroom","My Courses",`${heading("Combined Mathematics","Mr. Tharindu Jayasinghe · Physical Science")}<div class="classroom-layout"><div><div class="video-placeholder"><div><button class="play-button" id="playLesson">▶</button><b id="videoTitle">Introduction and syllabus overview</b><p style="font-size:10px;color:#c7d8f8">Demo lesson player · connect a video URL for playback</p></div></div><div class="panel" style="margin-top:15px"><h3 id="lessonHeading">Introduction and syllabus overview</h3><p class="panel-sub">Lesson 01 · Course chapter 1</p><p style="line-height:1.7;color:var(--muted);font-size:12px">Review the key learning objectives for this lesson. Use the lesson list to move through the course in order.</p><button class="btn btn-primary" id="completeLesson">✓ Mark as completed</button> <button class="btn btn-light" id="nextLesson">Next lesson →</button></div></div><div class="panel"><h3>Course lessons</h3><div class="lesson-list" id="lessonList"></div></div></div>`);function render(){ $("#lessonList").innerHTML=lessons.map((l,i)=>`<div class="lesson-item ${i===active?'active':''}" data-i="${i}"><strong>${String(i+1).padStart(2,"0")} · ${l}</strong><small>${i<2?"12":"18"} min · ${i<active?"Completed":"Video lesson"}</small></div>`).join("");$("#videoTitle").textContent=lessons[active];$("#lessonHeading").textContent=lessons[active];$$(".lesson-item").forEach(el=>el.addEventListener("click",()=>{active=+el.dataset.i;render()}))}render();$("#nextLesson").onclick=()=>{active=Math.min(active+1,lessons.length-1);render()};$("#completeLesson").onclick=e=>{e.target.textContent="✓ Completed";e.target.classList.add("btn-light")};$("#playLesson").onclick=()=>alert("Add your lesson video URL to enable playback.")}
function quiz(){if(!ensureUser())return;let questions=[{q:"What is the derivative of x²?",a:["x","2x","x²","2"],correct:1,why:"Using the power rule, d(xⁿ)/dx = nxⁿ⁻¹, so the derivative is 2x."},{q:"Which unit is used to measure electric current?",a:["Volt","Ohm","Ampere","Watt"],correct:2,why:"Electric current is measured in amperes (A)."},{"q":"Which data structure follows FIFO order?",a:["Stack","Queue","Tree","Graph"],correct:1,why:"A queue follows First In, First Out (FIFO)."}];let idx=0,answers={},seconds=180,timer; shell("Online examinations","Online Exams",`${heading("Quick knowledge check","A short mixed-subject practice quiz.")}<div class="panel" style="max-width:760px;margin:auto"><div style="display:flex;justify-content:space-between"><span class="pill">Practice quiz · 3 questions</span><b id="quizTimer">03:00</b></div><div class="progress-track" style="margin:18px 0"><span id="quizProgress" style="width:33%"></span></div><p class="panel-sub" id="questionCount"></p><h2 class="quiz-question" id="questionText"></h2><div id="answerList"></div><div style="display:flex;justify-content:space-between;margin-top:22px"><button class="btn btn-light" id="prevQuestion">← Previous</button><button class="btn btn-primary" id="nextQuestion">Next question →</button></div><div id="quizResult"></div></div>`);function render(){let q=questions[idx];$("#questionCount").textContent=`QUESTION ${idx+1} OF ${questions.length}`;$("#questionText").textContent=q.q;$("#answerList").innerHTML=q.a.map((a,i)=>`<label class="answer-option"><input type="radio" name="answer" value="${i}" ${answers[idx]===i?"checked":""}>${a}</label>`).join("");$("#quizProgress").style.width=((idx+1)/questions.length*100)+"%";$("#prevQuestion").disabled=idx===0;$("#nextQuestion").textContent=idx===questions.length-1?"Submit quiz":"Next question →"}render();$("#answerList").addEventListener("change",e=>{if(e.target.name==="answer")answers[idx]=+e.target.value});$("#prevQuestion").onclick=()=>{idx--;render()};$("#nextQuestion").onclick=()=>{if(idx<questions.length-1){idx++;render()}else finish()};function finish(){clearInterval(timer);let score=questions.filter((q,i)=>answers[i]===q.correct).length;$("#quizResult").innerHTML=`<hr><div class="result-score">${Math.round(score/questions.length*100)}%</div><h3>You scored ${score} out of ${questions.length}</h3>${questions.map((q,i)=>`<p style="font-size:11px"><b>${i+1}. ${q.a[q.correct]}</b> — ${q.why}</p>`).join("")}<button class="btn btn-primary" onclick="location.reload()">Try again</button>`;$("#nextQuestion").disabled=true;$("#prevQuestion").disabled=true}timer=setInterval(()=>{seconds--;$("#quizTimer").textContent=`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`;if(seconds<=0)finish()},1000)}
function live(){if(!ensureUser())return;shell("Live classes","Live Classes",`${heading("Live class schedule","Keep track of your upcoming online lessons.")}<div class="table-wrap"><table><thead><tr><th>Class</th><th>Teacher</th><th>Date</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody>${[["Physics: Electricity","Mr. Tharindu Jayasinghe","Today","7:00 PM","Upcoming"],["Combined Maths: Integration","Mr. Tharindu Jayasinghe","18 Nov 2026","4:30 PM","Upcoming"],["ICT: Database concepts","Ms. Nadeesha Silva","20 Nov 2026","6:00 PM","Upcoming"],["Biology: Genetics","Dr. Sachini Fernando","14 Nov 2026","5:00 PM","Completed"]].map((r,i)=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td><span class="pill ${i===3?'orange-pill':''}">${r[4]}</span></td><td>${i===3?"—":`<button class="action-link" onclick="alert('Demo meeting link: add your Zoom or Google Meet URL here.')">Join class ↗</button>`}</td></tr>`).join("")}</tbody></table></div>`)}
function assignments(){if(!ensureUser())return;shell("Assignments","Assignments",`${heading("Assignments","Submit your work before the deadlines.")}<div class="table-wrap"><table><thead><tr><th>Assignment</th><th>Subject</th><th>Deadline</th><th>Status</th><th>Action</th></tr></thead><tbody>${[["Differentiation worksheet","Combined Mathematics","22 Nov 2026","Not submitted"],["Electricity structured questions","Physics","25 Nov 2026","In progress"],["Database design task","ICT","28 Nov 2026","Submitted"]].map((r,i)=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td><td><span class="pill">${r[3]}</span></td><td>${i===2?"View feedback":`<label class="action-link" style="cursor:pointer">Upload file <input type="file" hidden accept=".pdf,.doc,.docx" onchange="alert('Selected: '+this.files[0].name+'. Connect server storage to submit this file.')"></label>`}</td></tr>`).join("")}</tbody></table></div>`)}
function profile(){if(!ensureUser())return;let u=current();shell("My profile","My Profile",`${heading("My profile","Manage your personal and academic information.",'<button class="btn btn-primary" data-modal="edit">Edit profile</button>')}<div class="profile-header"><div class="profile-large">${initials(u.name)}</div><div><h2>${u.name}</h2><p>${u.email} · ${u.role}</p></div></div><div class="content-grid"><div class="panel"><h3>Personal information</h3>${[["School",u.school||"Not added"],["District",u.district||"Not added"],["A/L stream",u.stream||"—"],["Examination year",u.year||"—"]].map(x=>`<div class="list-row"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join("")}</div><div class="panel"><h3>Learning statistics</h3><div class="stat-card"><small>Lessons completed</small><strong>28</strong></div><div class="stat-card" style="margin-top:10px"><small>Average quiz score</small><strong>82%</strong></div></div></div>`)}
function admin(){if(!ensureUser())return;if(current().role!=="admin"){location.href="dashboard.html";return}let users=JSON.parse(localStorage.getItem("sl_users")||"[]");shell("Administrator","Dashboard",`${heading("Admin overview","Manage the Smart Learning platform.")}<div class="grid-4"><div class="stat-card"><small>Registered students</small><strong>${users.filter(x=>x.role==="student").length+2480}</strong><span>↑ 8% this month</span></div><div class="stat-card"><small>Teachers</small><strong>24</strong><span>Active educators</span></div><div class="stat-card"><small>Courses</small><strong>${demoCourses.length}</strong><span>Across 5 streams</span></div><div class="stat-card"><small>Lessons</small><strong>850</strong><span>Published content</span></div></div><div class="content-grid"><div class="panel" id="students"><h3>Recent registered users</h3>${users.map(u=>`<div class="list-row"><div><strong>${u.name}</strong><small>${u.email}</small></div><span class="pill">${u.role}</span></div>`).join("")}</div><div class="panel" id="teachers"><h3>Platform management</h3>${["Manage courses","Upload learning materials","Manage assignments","Manage quizzes","Schedule live classes","Publish announcements","View student performance"].map(x=>`<div class="list-row"><strong>${x}</strong><button class="action-link" onclick="alert('Demo management action: ${x}. Connect a backend to save changes.')">Open →</button></div>`).join("")}</div></div>`,"admin")}
function teacher(){if(!ensureUser())return;if(current().role!=="teacher"){location.href="dashboard.html";return}shell("Teacher workspace","Dashboard",`${heading("Welcome, ${current().name}","Your teaching workspace at a glance.")}<div class="grid-4"><div class="stat-card"><small>Assigned courses</small><strong>3</strong></div><div class="stat-card"><small>Students</small><strong>186</strong></div><div class="stat-card"><small>Pending submissions</small><strong>12</strong></div><div class="stat-card"><small>Upcoming classes</small><strong>4</strong></div></div><div class="content-grid"><div class="panel"><h3>Your assigned courses</h3>${demoCourses.slice(0,3).map(c=>`<div class="list-row"><div><strong>${c.name}</strong><small>${c.lessons} lessons · ${c.stream}</small></div><span class="pill">Active</span></div>`).join("")}</div><div class="panel"><h3>Teaching tools</h3>${["Upload video lesson","Upload PDF notes","Create quiz","Create assignment","Schedule live class","Review submissions & feedback"].map(x=>`<div class="list-row"><strong>${x}</strong><button class="action-link" onclick="alert('Connect backend storage and teacher permissions for: ${x}')">Open →</button></div>`).join("")}</div></div>`,"teacher")}
const page=document.body.dataset.page;
if(page==="dashboard")dashboard();if(page==="courses")courses();if(page==="materials")materialPage();if(page==="classroom")classroom();if(page==="quizzes")quiz();if(page==="live")live();if(page==="assignments")assignments();if(page==="profile")profile();if(page==="admin")admin();if(page==="teacher")teacher();
document.querySelector(".menu-toggle")?.addEventListener("click",()=>document.querySelector(".top-nav")?.classList.toggle("open"));